using System;using System.IO;using System.Linq;using System.Collections;using UnityEngine;using UnityEngine.UI;using UnityEngine.EventSystems;using UnityEditor;using CatGunner.Runtime;
public static class ModeUiPreview {
 const string Dir="/Volumes/ZHITAI_1T/IdleCatGunner/art/reskin/penguin-expedition/mode-ui-v1";
 static GameClient Client(){if(Application.dataPath!="/Volumes/ZHITAI_1T/IdleCatGunner/reconstruction/CatGunnerUnityClient/Assets")throw new Exception("Wrong project");return UnityEngine.Object.FindAnyObjectByType<GameClient>(FindObjectsInactive.Include);}
 public static object Prepare(){var c=Client();if(Application.isPlaying)throw new Exception("EditMode required");var state=new{c.Persist,c.SaveFolderOverride,host=SessionState.GetString("CatGunner.Recovery.TestHostFolder","")};File.WriteAllText(Dir+"/preview-state.json",Newtonsoft.Json.JsonConvert.SerializeObject(state));SessionState.SetString("CatGunner.Recovery.TestHostFolder",Path.Combine(Application.temporaryCachePath,"ModeUiPreview-"+Guid.NewGuid().ToString("N")));c.Persist=false;return state;}
 public static object Restore(){var c=Client();if(Application.isPlaying)throw new Exception("EditMode required");var s=Newtonsoft.Json.Linq.JObject.Parse(File.ReadAllText(Dir+"/preview-state.json"));c.Persist=(bool)s["Persist"];c.SaveFolderOverride=s["SaveFolderOverride"].Type==Newtonsoft.Json.Linq.JTokenType.Null?null:(string)s["SaveFolderOverride"];SessionState.SetString("CatGunner.Recovery.TestHostFolder",(string)s["host"]);return new{c.Persist,c.SaveFolderOverride};}
 public static string Capture(string batch="before"){var c=Client();if(!Application.isPlaying||!c.SaveFolderOverride.Contains("ModeUiPreview"))throw new Exception("Isolated preview required");c.StartCoroutine(Run(c,batch));return "Capturing "+batch;}
 static IEnumerator Shot(string folder,string name){yield return new WaitForSecondsRealtime(.6f);yield return new WaitForEndOfFrame();var t=ScreenCapture.CaptureScreenshotAsTexture();try{File.WriteAllBytes(folder+"/"+name+".png",t.EncodeToPNG());}finally{UnityEngine.Object.Destroy(t);}}
 static IEnumerator Click(Button b){var module=EventSystem.current.GetComponent<StandaloneInputModule>();var mouse=module.gameObject.AddComponent<ForestFeedbackMouseFixture>();module.inputOverride=mouse;Canvas.ForceUpdateCanvases();var r=(RectTransform)b.transform;mouse.Position=RectTransformUtility.WorldToScreenPoint(null,r.TransformPoint(r.rect.center));yield return null;mouse.Down=mouse.Held=true;yield return null;mouse.Down=mouse.Held=false;mouse.Up=true;yield return null;mouse.Up=false;yield return null;module.inputOverride=null;UnityEngine.Object.Destroy(mouse);}
 static IEnumerator Run(GameClient c,string batch){while(!c.ReadyForPlay||!c.GetComponent<PenguinPlaytestPolish>().Ready)yield return null;string folder=Dir+"/"+batch;Directory.CreateDirectory(folder);c.DailyLogin.AutoShow=false;c.DailyLogin.Close();c.Tutorial.SetCleared();c.Offline.offlinePanelUI.gameObject.SetActive(false);c.MissionUI.Panel_Close();c.Forest.Stage_Value_Max=400;c.State.Stage_Value_Max=400;c.OfflinePurchaseSimulation=true;c.ContentUnlock.Reload();c.GetComponent<Language>().PersistSelection=false;c.GetComponent<Language>().Select("zh-CN");c.State.PetCoin=250;c.State.Dia=10000;c.ApplyBalance();ForestRuntimeAcceptance.IsGaming=false;
 var geometry=new System.Collections.Generic.List<object>();var canvas=c.Slider.GetComponentInParent<Canvas>();var menu=UiAuthoring.Find(canvas.transform,"SafeArea/Main_UI/Btn_list");
 yield return Shot(folder,"main");
 foreach(var key in new[]{"SpeedRun_Btn","Mine_Btn","Boss_Btn","Monster_Btn","Raid_Btn","Adventure_Btn","Pet_Btn ","Mission_Btn"}){
 var states=canvas.GetComponentsInChildren<Transform>(true).ToDictionary(t=>t.gameObject,t=>t.gameObject.activeSelf);var b=menu.GetComponentsInChildren<Button>(true).FirstOrDefault(t=>t.name==key);
 if(b==null){File.AppendAllText(folder+"/missing.txt",key+"\n");continue;}yield return Click(b);
 if(key=="Mission_Btn"){c.Missions.ResetSeason(true);c.State.Mission_TreeCount_Value=1585;c.State.Mission_StageClear_Value=13;c.State.Mission_Reward_Lv=2;c.State.Mission_Reward_Exp=45;c.MissionUI.UI_Reload();}
 yield return Shot(folder,key.Trim().Replace("_Btn",""));
 var visible=c.gameObject.scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<PenguinModeViewport>(true)).Where(v=>v.gameObject.activeInHierarchy).ToArray();
 foreach(var v in visible){var bounds=v.GetComponentsInChildren<Image>(false).Where(i=>i.name=="NonPurchase_Panel"||i.name=="Active_Panel"||i.name=="Panel"&&i.transform.parent==v.transform).Select(i=>{var corners=new Vector3[4];i.rectTransform.GetWorldCorners(corners);var points=corners.Select(x=>RectTransformUtility.WorldToScreenPoint(null,x)).ToArray();return new{path=v.name+"/"+i.name,minX=points.Min(x=>x.x),maxX=points.Max(x=>x.x),minY=points.Min(x=>x.y),maxY=points.Max(x=>x.y),alpha=i.color.a,opaque=i.color.a==1,sprite=i.sprite!=null?i.sprite.name:null,inViewport=points.All(x=>x.x>=-1&&x.x<=Screen.width+1&&x.y>=-1&&x.y<=Screen.height+1)};}).ToArray();geometry.Add(new{mode=v.name,bounds});}

 if(key=="Mine_Btn"){c.State.Is_Mine_Pack=true;c.MineMode.mineStart_ui.Reload();yield return Shot(folder,"Mine-plus-pack");c.State.Is_Mine_Pack=false;}
 if(key=="Pet_Btn "&&batch.StartsWith("after")){int before=c.State.PetCoin;var draw=c.PetUI.Pet_UI_obj.GetComponentsInChildren<Button>(true).Single(t=>t.name=="Draw_Btn");c.PetUI.Pet_Reload();yield return Click(draw);yield return Shot(folder,"Pet-draw");File.WriteAllText(folder+"/pet-draw.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{before,after=c.State.PetCoin,consumed=before-c.State.PetCoin,success=before-c.State.PetCoin==100,glyph=draw.transform.Find("Price_txt").GetComponent<TMPro.TMP_Text>().spriteAsset.name}));c.PetUI.newPet_ui.gameObject.SetActive(false);}

 foreach(var pair in states)if(pair.Key!=null&&pair.Key.activeSelf!=pair.Value)pair.Key.SetActive(pair.Value);
 }
 File.WriteAllText(folder+"/geometry.json",Newtonsoft.Json.JsonConvert.SerializeObject(geometry,Newtonsoft.Json.Formatting.Indented));
 File.WriteAllText(folder+"/complete.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{width=Screen.width,height=Screen.height,c.SaveFolderOverride,c.Persist,frames=Directory.GetFiles(folder,"*.png").Length,source="Unity Editor GPU frames; menu clicks through StandaloneInputModule"}));}
}
